#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-27
#
# Unreachable Skill Detector: see the full contract below `set`.

# strict-mode: opt-out this detector's whole job is counting grep misses; `set -e`
# would abort the scan on the first skill that has no inbound reference, which is
# exactly the case it exists to report. Matches tests/orphans/test-orphan-*.sh.
set -uo pipefail

# =============================================================================
# Unreachable Skill Detector
# =============================================================================
# The complement of tests/manifests/test-skill-activation-channels.mjs.
# That gate covers `user-invocable: true` skills (islands: reachable only by
# typing the slash command). This gate covers the OTHER half of the matrix:
# skills nobody can invoke at all.
#
# Reachability model (per src/skills/CONTRIBUTING-SKILLS.md lines 124-125):
#   user-invocable: true            -> reachable, a human can type /ork:<name>
#   disable-model-invocation: false -> reachable, CC auto-selects on description
#   otherwise                       -> the ONLY remaining load path is being
#                                      named in a `skills:` frontmatter list on
#                                      an agent (src/agents/*.md) or on another
#                                      skill (src/skills/*/SKILL.md).
#
# So a skill FAILS this gate when all of these hold:
#   1. disable-model-invocation: true   (the model cannot pick it)
#   2. user-invocable is false/absent   (no slash command)
#   3. it is not named in any agent or skill `skills:` frontmatter list
# Such a skill costs bytes in the plugin and cannot be invoked by anyone.
#
# Failures are reported in two flavours:
#   [DEAD]        criteria 1-3 AND zero textual mentions anywhere in the repo
#                 scan set. Nothing at all points at it.
#   [UNREACHABLE] criteria 1-3 but prose elsewhere still name-drops it. The
#                 mention is documentation, not a load path: reading "see
#                 checkpoint-resume" in another SKILL.md does not load the
#                 skill when model invocation is disabled.
# Both fail. The split exists so a reviewer can tell "delete it" from
# "wire it up, something clearly wanted it".
#
# SAFETY: this gate can motivate deletions, so it self-checks its own parser
# before trusting a negative result (see PARSER SELF-CHECK below). A prior
# manual audit concluded `grep "^skills:" src/agents/*.md` returned nothing and
# therefore that 39 skills were unreachable. That grep actually returns 36 of
# 36 agents, and acting on the false reading would have deleted 30 wired
# skills. A parser that silently finds zero wiring must abort, not accuse.
#
# Usage: bash tests/orphans/test-unreachable-skills.sh [--verbose]
# Exit:  0 = every skill is reachable, 1 = unreachable skill(s) found
# Env:   ORK_UNREACHABLE_SKILLS_ADVISORY=1  report but exit 0
# =============================================================================

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"
cd "$REPO_ROOT" || exit 1

SKILLS_DIR="src/skills"
AGENTS_DIR="src/agents"

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
BLUE='\033[0;34m'; BOLD='\033[1m'; NC='\033[0m'

ADVISORY="${ORK_UNREACHABLE_SKILLS_ADVISORY:-0}"
VERBOSE=""
for arg in "$@"; do [[ "$arg" == "--verbose" ]] && VERBOSE="1"; done

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

# Places an inbound reference can legitimately live. docs/ is deliberately out:
# a docs mention is not a load path.
SCAN_PATHS=("$AGENTS_DIR" "$SKILLS_DIR" "manifests" "src/hooks/src" "tests" ".github/workflows")
EXISTING_SCAN_PATHS=()
for p in "${SCAN_PATHS[@]}"; do [[ -e "$p" ]] && EXISTING_SCAN_PATHS+=("$p"); done

# Generated per-skill scaffolding. These files exist for EVERY skill by
# construction, so counting them as inbound references makes the gate vacuous.
#   tests/evals/skills/<name>.eval.*      the skill's own eval spec
#   tests/evals/eval-plan-playground.html generated index naming ~79 skills
is_generated_companion() {  # $1=file $2=skill name
    case "$1" in
        tests/evals/skills/"$2".*) return 0 ;;
        tests/evals/eval-plan-playground.html) return 0 ;;
    esac
    return 1
}

# ---- extract every name in a YAML frontmatter `skills:` list ----------------
# Handles block form ("skills:" then "  - name") and inline form
# ("skills: [a, b]"). Scoped to frontmatter (between the 1st and 2nd `---`) so
# prose such as `description: "... loaded via skills: field ..."` cannot leak in.
extract_wired() {
    awk '
      FNR==1 { fm=0; inblock=0 }
      /^---[[:space:]]*$/ { fm++; next }
      fm != 1 { next }
      /^skills:[[:space:]]*\[/ {
          s=$0; sub(/^skills:[[:space:]]*\[/,"",s); sub(/\].*$/,"",s)
          gsub(/["'"'"']/,"",s)
          n=split(s,a,",")
          for (i=1;i<=n;i++) { gsub(/^[[:space:]]+|[[:space:]]+$/,"",a[i]); if (a[i]!="") print a[i] }
          next
      }
      /^skills:[[:space:]]*$/ { inblock=1; next }
      inblock && /^[[:space:]]*-[[:space:]]+/ {
          s=$0; sub(/^[[:space:]]*-[[:space:]]+/,"",s); sub(/[[:space:]]*#.*$/,"",s)
          gsub(/["'"'"']/,"",s); gsub(/^[[:space:]]+|[[:space:]]+$/,"",s)
          if (s!="") print s
          next
      }
      inblock { inblock=0 }
    ' "$@"
}

echo -e "${BLUE}${BOLD}Unreachable skill detector${NC}"
echo ""

extract_wired "$AGENTS_DIR"/*.md "$SKILLS_DIR"/*/SKILL.md | sort -u > "$TMP/wired.txt"
agents_declaring="$(grep -l '^skills:' "$AGENTS_DIR"/*.md | wc -l | tr -d ' ')"
wired_count="$(grep -c . < "$TMP/wired.txt" | tr -d ' ')"

# ---- PARSER SELF-CHECK -----------------------------------------------------
# Every accusation this gate makes is an argument from absence, so a parser
# that reads nothing would accuse everything. Floors are set far below the
# real values so ordinary churn never trips them, but a broken regex or a
# moved directory does.
#
# 2026-07-27: 36 agents / 96 names, floors 30 / 60.
# 2026-07-31: #3221 removed 94 DEAD skill preload declarations from src/agents,
#   which legitimately cut distinct wired names 96 -> 52 and tripped the 60
#   floor. Verified both directions: at 8e6213b4f~1 this gate exits 0 with
#   "Every skill is reachable"; at #3221 it ABORTs on the name floor alone
#   (agent count held at 36). The repo genuinely shrank, so the floor comes
#   down. 45 still catches the failure this guard exists for, a parser
#   returning near-zero, while leaving room for further dead-edge cleanup.
MIN_AGENTS_DECLARING=30
MIN_WIRED_NAMES=45
if [[ "$agents_declaring" -lt "$MIN_AGENTS_DECLARING" || "$wired_count" -lt "$MIN_WIRED_NAMES" ]]; then
    echo -e "${RED}${BOLD}ABORT: reference parser looks broken, refusing to accuse anything.${NC}"
    echo "  agents declaring 'skills:'  : $agents_declaring (floor $MIN_AGENTS_DECLARING)"
    echo "  distinct wired skill names  : $wired_count (floor $MIN_WIRED_NAMES)"
    echo ""
    echo "  Fix the parser (or the floors, if the repo genuinely shrank) before"
    echo "  trusting any orphan verdict from this gate."
    exit 1
fi

echo "  Wiring sources: $agents_declaring agent file(s) declaring 'skills:', $wired_count distinct skill name(s) wired"

# ---- 4TH ACTIVATION PATH (#3313) --------------------------------------------
# An explicit body Read("${CLAUDE_PLUGIN_ROOT}/skills/<x>/SKILL.md") in an
# agent is a live load path: #3221 converted 7 load-bearing preload edges into
# exactly these lines and test-agent-read-path-truthful.mjs ratchets them.
# Kept SEPARATE from wired.txt on purpose: wired_count feeds the parser
# self-check floor above, and blending would make that floor measure a
# different population. This extractor gets its own floor for the same
# reason the script guards MIN_WIRED_NAMES: the gate argues from absence, so
# an extractor that silently returns 0 would re-accuse the skills it exists
# to exonerate. Live count at introduction: 8 names across 9 lines. A grep
# miss cannot hide here: the floor below catches an empty extraction.
grep -hoE 'Read\("\$\{CLAUDE_PLUGIN_ROOT\}/skills/[a-z0-9-]+/SKILL\.md"\)' "$AGENTS_DIR"/*.md \
    | sed -E 's|.*/skills/([a-z0-9-]+)/SKILL\.md.*|\1|' | sort -u > "$TMP/readpath.txt" || true # silent: gating-relaxed
readpath_count="$(grep -c . < "$TMP/readpath.txt" | tr -d ' ')"
MIN_READ_PATH_NAMES=6
if [[ "$readpath_count" -lt "$MIN_READ_PATH_NAMES" ]]; then
    echo -e "${RED}${BOLD}ABORT: agent-body Read() extractor looks broken, refusing to accuse anything.${NC}"
    echo "  distinct Read()-path skill names: $readpath_count (floor $MIN_READ_PATH_NAMES)"
    echo "  If agents legitimately dropped below the floor, lower it WITH the change"
    echo "  that removed the Read() lines, the way MIN_WIRED_NAMES was lowered in #3221."
    exit 1
fi
echo "  Read()-path sources: $readpath_count distinct skill name(s) loaded via agent body Read()"

dead=()
unreachable=()
candidates=0
total=0

for skill_md in "$SKILLS_DIR"/*/SKILL.md; do
    [[ -f "$skill_md" ]] || continue
    name="$(basename "$(dirname "$skill_md")")"
    # src/skills/shared/ holds rules+assets and src/skills/CONTRIBUTING-SKILLS.md
    # is a doc; neither has a SKILL.md, but guard explicitly anyway.
    [[ "$name" == "shared" ]] && continue
    total=$((total + 1))

    fm="$(awk '/^---[[:space:]]*$/{n++; next} n==1' "$skill_md")"
    ui="$(printf '%s\n' "$fm" | awk '/^user-invocable:/{print $2; exit}')"
    dmi="$(printf '%s\n' "$fm" | awk '/^disable-model-invocation:/{print $2; exit}')"

    # Reachable by a human typing the slash command.
    [[ "$ui" == "true" ]] && continue
    # Reachable by the model auto-selecting on description match.
    [[ "$dmi" == "true" ]] || continue

    candidates=$((candidates + 1))

    # Load path 3: named in an agent's or skill's skills: list.
    if grep -qxF -- "$name" "$TMP/wired.txt"; then
        [[ -n "$VERBOSE" ]] && echo -e "  ${GREEN}[OK]${NC} $name (preloaded via a skills: frontmatter list)"
        continue
    fi

    # Load path 4 (#3313): loaded by an explicit agent body Read().
    if grep -qxF -- "$name" "$TMP/readpath.txt"; then
        [[ -n "$VERBOSE" ]] && echo -e "  ${GREEN}[OK]${NC} $name (loaded via agent body Read())"
        continue
    fi

    # Not wired. Gather textual evidence to classify DEAD vs UNREACHABLE.
    mentions=()
    while IFS= read -r hit; do
        [[ -z "$hit" ]] && continue
        case "$hit" in "$SKILLS_DIR/$name/"*) continue ;; esac
        is_generated_companion "$hit" "$name" && continue
        mentions+=("$hit")
    done < <(grep -rlF -e "$name" "${EXISTING_SCAN_PATHS[@]}")

    if [[ ${#mentions[@]} -eq 0 ]]; then
        dead+=("$name")
        echo -e "  ${RED}[DEAD]${NC} $name: no slash command, model invocation disabled, zero mentions anywhere"
    else
        unreachable+=("$name")
        echo -e "  ${RED}[UNREACHABLE]${NC} $name: no slash command, model invocation disabled, no skills: wiring"
        printf '        mentioned in (prose only, not a load path): %s\n' "${mentions[0]}"
        [[ ${#mentions[@]} -gt 1 ]] && printf '        (+%d more file(s))\n' "$((${#mentions[@]} - 1))"
    fi
done

failures=$((${#dead[@]} + ${#unreachable[@]}))

echo ""
echo "  Skills scanned            : $total"
echo "  Non-invocable candidates  : $candidates (user-invocable false/absent AND disable-model-invocation: true)"
if [[ $failures -gt 0 ]]; then
    echo -e "  Unreachable               : ${RED}$failures${NC}"
else
    echo -e "  Unreachable               : ${GREEN}0${NC}"
fi
echo ""

if [[ $failures -eq 0 ]]; then
    echo -e "${GREEN}✓ Every skill is reachable by a human, the model, or a skills: frontmatter list${NC}"
    exit 0
fi

echo -e "${YELLOW}To fix each one, pick exactly one:${NC}"
echo "  • wire it  : add the name to a src/agents/<agent>.md or src/skills/<skill>/SKILL.md 'skills:' list"
echo "  • expose it: set 'user-invocable: true' so /ork:<name> reaches it"
echo "  • open it  : set 'disable-model-invocation: false' so CC auto-selects on description"
echo "  • delete it: remove src/skills/<name>/ and rebuild"
echo ""

if [[ "$ADVISORY" == "1" ]]; then
    echo -e "${YELLOW}(ORK_UNREACHABLE_SKILLS_ADVISORY=1: reporting only, not failing.)${NC}"
    exit 0
fi

echo -e "${RED}✗ $failures unreachable skill(s).${NC}"
exit 1
